<script setup lang="ts">
import { computed, ref } from 'vue'
const dataset=ref('A'), selected=ref(0), state=ref('ready')
const labels=['Jan','Feb','Mar','Apr','May','Jun']
const rows=computed(()=>{
 const values=dataset.value==='A'?[35,48,41,61,56,74]:[42,36,55,48,72,64]
 return values.map((v,i)=>({open:v+100,high:v+115,low:v+85,close:v+100+(dataset.value==='flat'?0:i%2?-9:9)}))
})
const x=(i:number)=>40+i*48
const y=(v:number)=>170-(v-100)*1.4
const direction=(r:{open:number,close:number})=>r.close>r.open?'Up':r.close<r.open?'Down':'Flat'
function reset(){dataset.value='A';selected.value=0;state.value='ready'}
</script>
<template>
<section class="candle-demo" aria-label="Local candlestick example"><p>Synthetic monthly OHLC in sample currency units. No prices are live and no trade can be placed.</p><div class="candle-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="flat">Flat closes</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><template v-if="state==='ready'"><p class="candle-legend">Filled: close above open · hollow: close below open · horizontal tick: equal. Wick: low to high. Fixed axis100–200.</p><svg :key="dataset" viewBox="0 0 320 210" role="img" aria-label="Synthetic monthly open, high, low and close; vertical scale100 to200. Exact values follow in a table."><g v-for="tick in [100,125,150,175,200]" :key="tick"><line x1="36" x2="292" :y1="y(tick)" :y2="y(tick)" class="candle-grid"/><text x="4" :y="y(tick)+4">{{ tick }}</text></g><g v-for="(r,i) in rows" :key="i" class="candle-mark" :class="{selected:selected===i}"><line class="candle-wick" :x1="x(i)" :x2="x(i)" :y1="y(r.high)" :y2="y(r.low)"/><rect v-if="r.open!==r.close" class="candle-body" :class="{hollow:r.close<r.open}" :x="x(i)-8" :y="y(Math.max(r.open,r.close))" width="16" :height="Math.abs(r.close-r.open)*1.4"/><line v-else class="candle-flat" :x1="x(i)-8" :x2="x(i)+8" :y1="y(r.open)" :y2="y(r.open)"/><text :x="x(i)" y="194" text-anchor="middle">{{ labels[i] }}</text></g></svg><div role="group" aria-label="Select month" class="candle-months"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @focus="selected=i" @click="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: Open {{ rows[selected].open }}, High {{ rows[selected].high }}, Low {{ rows[selected].low }}, Close {{ rows[selected].close }}. {{ direction(rows[selected]) }}.</p><table class="candle-data"><caption>Exact OHLC, sample currency units, dataset {{ dataset }}</caption><thead><tr><th scope="col">Month</th><th scope="col"><abbr title="Open">O</abbr></th><th scope="col"><abbr title="High">H</abbr></th><th scope="col"><abbr title="Low">L</abbr></th><th scope="col"><abbr title="Close">C</abbr></th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="i"><th scope="row">{{ labels[i] }}</th><td>{{ r.open }}</td><td>{{ r.high }}</td><td>{{ r.low }}</td><td>{{ r.close }}</td></tr></tbody></table><p class="candle-key">O: Open · H: High · L: Low · C: Close. Direction compares close with open, not the previous month's close.</p></template><p v-else role="status" class="candle-state">{{ state==='loading'?'Loading demonstration only; no request is running. Prices are withheld.':'No sample observations in this state. Choose Ready to recover.' }}</p></section>
</template>
<style scoped>
.candle-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.candle-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.candle-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.candle-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.candle-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.candle-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.candle-legend,.candle-key{font-size:12px}.candle-demo svg{display:block;width:100%;height:auto;max-height:330px;margin:16px 0;animation:candle-in .2s ease-out}.candle-demo svg text{fill:var(--vp-c-text-2);font-size:10px}.candle-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 4}.candle-wick,.candle-flat{stroke:var(--vp-c-brand-1);stroke-width:1.5}.candle-body{fill:var(--vp-c-brand-1);stroke:var(--vp-c-brand-1);stroke-width:1.5}.candle-body.hollow{fill:var(--vp-c-bg)}.candle-mark.selected :is(line,rect){stroke:var(--vp-c-text-1);stroke-width:2.5}.candle-months{display:flex;gap:6px;flex-wrap:wrap}.candle-months button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.candle-data{display:table!important;width:100%;font-size:12px}.candle-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.candle-data :is(td,th){padding:6px!important}.candle-data abbr{text-decoration:none}.candle-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}@keyframes candle-in{from{opacity:.4}to{opacity:1}}@media(prefers-reduced-motion:reduce){.candle-demo svg{animation:none}}
</style>
